# --- the repo half (always built) ------------------------------------------------------------------------

def title_of(text: str, rel: str) -> str:
    m = re.search(r"^#\s+(.+)$", text, re.M)
    return m.group(1).strip() if m else Path(rel).stem.replace("-", " ").capitalize()


def documents(root: Path, patterns: list[str]) -> list[dict[str, str]]:
    out, seen = [], set()
    base = root.resolve()
    for pattern in patterns:
        if not isinstance(pattern, str) or pattern.startswith(("/", "\\")) or ".." in pattern:
            continue
        for path in sorted(root.glob(pattern)):
            try:
                rel = path.resolve().relative_to(base).as_posix()
            except ValueError:
                continue  # a link out of the repo
            if rel in seen or not path.is_file() or path.name == "README.md" and "sources" in path.parts:
                continue
            seen.add(rel)
            text = s.read(path)
            if len(text) > DOC_LIMIT:
                text = text[:DOC_LIMIT] + "\n\n(cut here: the rest is in the repo)"
            out.append({"path": rel, "title": title_of(text, rel), "text": text})
    return out


def group_of(rel: str) -> str:
    """business, product or technical: where a document sits in the journey."""
    parts = rel.split("/")
    if parts[0] == "specs" and len(parts) > 2:
        return "product" if parts[2] in ("spec.md", "ux") else "technical"
    if parts[0] == "docs":
        return "product" if len(parts) > 2 and parts[1] == "product" else "technical"
    if parts[0] == ".specify":
        return "technical"
    return "business"


def grouped_documents(root: Path, patterns: list[str]) -> list[dict[str, str]]:
    """The founder's list plus the product and technical documents, each with its group, feature and last change."""
    docs = documents(root, list(patterns) + PRODUCT_DOCS + TECHNICAL_DOCS)[:DOC_COUNT_LIMIT]
    for d in docs:
        d["group"] = group_of(d["path"])
        parts = d["path"].split("/")
        d["feature"] = parts[1] if parts[0] == "specs" and len(parts) > 2 else ""
        d["updated"] = (s.git(root, "log", "-1", "--format=%cI", "--", d["path"]) or "").strip()
    return docs


def repo_data(root: Path, cfg_dash: dict[str, Any]) -> dict[str, Any]:
    cfg = s.config(root)
    pol = heartbeat.policy(root)
    slices = s.slices(root, cfg)
    roles = s.epic_roles(root)
    epics = []
    for code, ep in sorted(slices["epics"].items()):
        stories = [st for st in slices["stories"] if st.get("epic") == code]
        epics.append({"code": code, "name": (ep or {}).get("name", code), "goal": (ep or {}).get("goal", ""),
                      "role": roles.get(code, "engineer"), "stories": len(stories),
                      "slices": sorted({str(st.get("slice", "")) for st in stories if st.get("slice")})})
    memos = [d for d in documents(root, ["founder/board/*.md"]) if not d["path"].endswith("README.md")]
    beats = {r: {k: ((pol.get("roles") or {}).get(r) or {}).get(k) for k in ("enabled", "cron", "monthly_budget_usd")}
             for r in heartbeat.BUDGET_ROLES}
    return {
        "goals": goals.build(root),
        "documents": grouped_documents(root, cfg_dash.get("documents") or DEFAULT_DOCS),
        "roadmap": build_roadmap.build(root),
        "schedule": schedule(root, cfg),
        "trace": build_traceability.build(root),
        "team": build_team.build(root),
        "team_doc": s.read(root / "founder" / "team.md")[:DOC_LIMIT],
        "heartbeats": beats,
        "memos": memos,
        "epics": epics,
        "decisions": s.decisions(root, cfg),
        "approved_words": cfg.get("approved_words") or ["Approved"],
        "reports_to": dict(tickets.REPORTS_TO),
    }


# --- the roadmap timeline (Gantt) -----------------------------------------------------------------------

HISTORY_COMMITS = 200     # how far back the timeline reads a file's history for when a status changed


def day(v: Any) -> str:
    """A YYYY-MM-DD date, or "" when `v` isn't one."""
    raw = str(v or "").strip()[:10]
    try:
        return dt.date.fromisoformat(raw).isoformat() if re.fullmatch(r"\d{4}-\d{2}-\d{2}", raw) else ""
    except ValueError:
        return ""


def stage_state(status: Any) -> str:
    st = str(status or "").lower()
    return "done" if re.search(r"pass|defer|done", st) else "progress" if "current" in st else "todo"


def slice_state(status: Any) -> str:
    st = str(status or "").lower()
    return "done" if st == "done" else "progress" if re.search(r"progress|build|review|current", st) else "todo"


def stage_states(text: str) -> dict[str, str]:
    return {str(x["stage"]): stage_state(x["status"]) for x in s.playbook_text(text)}


def slice_states(text: str) -> dict[str, str]:
    try:
        data = json.loads(text or "{}")
    except ValueError:
        return {}
    rows = data.get("slices") if isinstance(data, dict) else None
    return {str(x.get("id")): slice_state(x.get("status")) for x in rows or [] if isinstance(x, dict) and x.get("id")}


def history(root: Path, rel: str, states: Any) -> dict[str, dict[str, str]]:
    """When each item's status in `rel` first moved to in progress (started) and to done (finished), from git.

    Oldest commit first; an item that goes back to to do loses both dates, one reopened loses its finish date.
    """
    log = s.git(root, "log", f"-{HISTORY_COMMITS}", "--format=%H %cI", "--", rel) or ""
    out: dict[str, dict[str, str]] = {}
    for line in reversed(log.strip().splitlines()):
        sha, _, when = line.partition(" ")
        text = s.git(root, "show", f"{sha}:{rel}")
        if text is None:
            continue
        date = day(when)
        for key, state in states(text).items():
            d = out.setdefault(key, {"started": "", "finished": ""})
            if state == "todo":
                d["started"] = d["finished"] = ""
                continue
            d["started"] = d["started"] or date
            d["finished"] = (d["finished"] or date) if state == "done" else ""
    return out


def schedule(root: Path, cfg: dict[str, Any]) -> dict[str, Any]:
    """The roadmap timeline: stages (grouped by phase in the page) and slices, each with planned and actual dates.

    Planned: optional `Start` and `Target` columns in founder/playbook.md, and `start` and `target` on each
    slice in founder/slices.json. Actual: the commits that moved its status to in progress and to done.
    """
    slices_rel = str(cfg.get("slices_file") or "founder/slices.json")
    stage_hist = history(root, "founder/playbook.md", stage_states)
    slice_hist = history(root, slices_rel, slice_states)
    rows: list[dict[str, Any]] = []
    for x in s.playbook(root):
        h = stage_hist.get(str(x["stage"])) or {}
        rows.append({"kind": "stage", "id": str(x["stage"]), "name": x["name"], "phase": x["phase"],
                     "status": x["status"], "state": stage_state(x["status"]), "start": day(x.get("start")),
                     "target": day(x.get("target")), "started": h.get("started", ""), "finished": h.get("finished", "")})
    for x in s.slices(root, cfg)["slices"]:
        if not isinstance(x, dict) or not x.get("id"):
            continue
        h = slice_hist.get(str(x["id"])) or {}
        rows.append({"kind": "slice", "id": str(x["id"]), "name": str(x.get("name", "")), "phase": "",
                     "status": str(x.get("status", "todo")), "state": slice_state(x.get("status")),
                     "start": day(x.get("start")), "target": day(x.get("target") or x.get("due")),
                     "started": h.get("started", ""), "finished": h.get("finished", "")})
    return {"rows": rows}


# --- the GitHub half (best effort) -----------------------------------------------------------------------

def all_comments(hub: tickets.Hub, n: int, pages: int = 20) -> list[dict[str, Any]]:
    out: list[dict[str, Any]] = []
    for page in range(1, pages + 1):
        got = hub.api(f"issues/{n}/comments?per_page=100&page={page}") or []
        out += got
        if len(got) < 100:
            break
    return out


def approvals(hub: tickets.Hub, root: Path) -> list[dict[str, Any]]:
    pol = approval.policy(root)
    who = approval.founders(pol, hub.repo)
    open_ = hub.tickets("open", approval.LABEL)
    closed = sorted(hub.tickets("closed", approval.LABEL), key=lambda i: -i["number"])[:15]
    out = []
    for issue in [*open_, *closed]:
        d = approval.decide(hub.api(f"issues/{issue['number']}/comments?per_page=100") or [], who)
        gate = next((lb[5:] for lb in tickets.labels_of(issue) if lb.startswith("gate:")), "")
        body = issue.get("body") or ""
        scope = (re.search(r"\*\*Scope:\*\* (.*)", body) or [None, ""])[1].strip()
        by = (re.search(r"\*\*Requested by:\*\* (.*)", body) or [None, ""])[1].strip()
        out.append({"number": issue["number"], "title": issue.get("title", ""), "url": issue.get("html_url", ""),
                    "gate": gate, "state": d["state"], "kind": d["kind"], "note": d["note"], "scope": scope,
                    "by": by, "open": issue.get("state") == "open", "created": issue.get("created_at", "")})
    return out


def costs(hub: tickets.Hub, root: Path, month: str, now: dt.datetime | None = None) -> dict[str, Any]:
    """The month's spend per role against budget, the run log, spend grouped four ways, and a month-end forecast."""
    pol = heartbeat.policy(root)
    runs = heartbeat.entries(heartbeat.Costs(hub, month).comments(), month)
    totals: dict[str, float] = {}
    for r in runs:
        totals[r["role"]] = totals.get(r["role"], 0.0) + r["usd"]
    roles = []
    for role in heartbeat.BUDGET_ROLES:
        cap, used, base = heartbeat.standing(hub, root, pol, role, month, totals) if pol.get("roles") else (None, totals.get(role, 0.0), 0.0)
        mine = [r for r in runs if r["role"] == role]
        daily: dict[str, float] = {}
        for r in mine:
            if r["at"][:10]:
                daily[r["at"][:10]] = round(daily.get(r["at"][:10], 0.0) + r["usd"], 4)
        roles.append({"role": role, "used": round(used, 4), "cap": cap, "base": base or None,
                      "stats": heartbeat.run_stats(mine), "daily": [{"date": d, "usd": v} for d, v in sorted(daily.items())]})

    def group(key: str, none: str) -> list[dict[str, Any]]:
        out: dict[str, dict[str, Any]] = {}
        for r in runs:
            g = out.setdefault(r[key] or none, {"key": r[key] or none, "usd": 0.0, "runs": 0})
            g["usd"], g["runs"] = round(g["usd"] + r["usd"], 4), g["runs"] + 1
        return sorted(out.values(), key=lambda g: -g["usd"])
    total = round(sum(totals.values()), 4)
    today = (now or dt.datetime.now(dt.timezone.utc)).date()
    ccap, _, cbase = heartbeat.standing(hub, root, pol, heartbeat.COMPANY, month, totals)
    return {"month": month, "roles": roles, "entries": runs[-200:], "total": total,
            "company": {"cap": ccap, "base": cbase or None, "used": total},
            "forecast": heartbeat.forecast(total, month, today),
            "cap_total": round(sum(r["cap"] or 0 for r in roles), 4),
            "by": {"objective": group("objective", "no objective"), "role": group("role", "?"),
                   "model": group("model", "not recorded"), "outcome": group("outcome", "not recorded")}}


def when_of(text: Any) -> dt.datetime | None:
    """An ISO date or time from GitHub or the repo, as UTC; None when it isn't one."""
    raw = str(text or "").strip()
    if not raw:
        return None
    try:
        d = dt.datetime.fromisoformat(raw.replace("Z", "+00:00"))
    except ValueError:
        return None
    return d if d.tzinfo else d.replace(tzinfo=dt.timezone.utc)


def trends(runs: list[dict[str, Any]], activity: list[dict[str, Any]], merged: list[dict[str, Any]],
           now: dt.datetime | None, days: int = TREND_DAYS) -> dict[str, Any]:
    """The last `days` days, one row per day: runs (worked, other), success rate, agent actions, merges."""
    today = (now or dt.datetime.now(dt.timezone.utc)).date()
    keys = [(today - dt.timedelta(days=days - 1 - i)).isoformat() for i in range(days)]
    rows = {k: {"date": k, "worked": 0, "other": 0, "tried": 0, "actions": 0, "merged": 0} for k in keys}
    for r in runs:
        d = when_of(r.get("at"))
        row = rows.get(d.date().isoformat()) if d else None
        if row is None:
            continue
        row["worked" if r.get("outcome") == "worked" else "other"] += 1
        row["tried"] += 1 if r.get("outcome") and r.get("outcome") != "no-work" else 0
    for a in activity:
        d = when_of(a.get("at"))
        if d and d.date().isoformat() in rows:
            rows[d.date().isoformat()]["actions"] += 1
    for p in merged:
        d = when_of(p.get("merged"))
        if d and d.date().isoformat() in rows:
            rows[d.date().isoformat()]["merged"] += 1
    out = []
    for k in keys:
        row = rows[k]
        row["success"] = round(row["worked"] / row["tried"], 4) if row["tried"] else None
        out.append(row)
    return {"days": out}


def needs_you(data: dict[str, Any], now: dt.datetime, stale_hours: float = STALE_HOURS) -> dict[str, Any]:
    """Everything waiting on the founder in one list: urgency first, then what only they can unblock, then age."""
    repo, gh_ = data.get("repo") or {}, data.get("github") or {}
    road = repo.get("roadmap") or {}
    items: list[dict[str, Any]] = []

    def add(kind: str, title: str, url: str = "", since: Any = "", detail: str = "", **extra: Any) -> None:
        d = when_of(since)
        age = (now - d).total_seconds() / 86400 if d else None
        overdue = APPROVAL_OVERDUE_DAYS if kind == "approval" else OVERDUE_DAYS
        level = "escalated" if age is not None and age >= ESCALATE_DAYS else \
            "overdue" if age is not None and age >= overdue else "new"
        items.append({"kind": kind, "title": clip(title, 200), "url": url, "since": str(since or ""),
                      "age_days": round(age, 1) if age is not None else None, "level": level,
                      "detail": clip(detail, 200), **extra})
    stuck: list[dict[str, Any]] = []
    if gh_.get("ok"):
        waiting = [a for a in gh_.get("approvals") or [] if a.get("open") and a.get("state") == "waiting"]
        for a in waiting:
            c = when_of(a.get("created"))
            left = approval.EXPIRE_DAYS - (now - c).days if c else None
            add("approval", a.get("title", ""), a.get("url", ""), a.get("created"),
                f"{a.get('gate') or 'gate'} gate, requested by {a.get('by') or 'an agent'}"
                + (" (resubmitted after your /revise)" if a.get("kind") == "resubmitted" else "")
                + (f"; expires in {left} days" if left is not None and 0 < left <= 7 else ""),
                number=a.get("number"), gate=a.get("gate", ""))
        asked = {a.get("scope") for a in waiting if a.get("gate") == "budget"}
        month = (gh_.get("costs") or {}).get("month", "")
        co = (gh_.get("costs") or {}).get("company") or {}
        if co.get("cap") and co.get("used", 0) >= co["cap"] and heartbeat.scope(heartbeat.COMPANY, month) not in asked:
            add("budget", "Every agent stopped: the company AI budget is spent", "", "",
                f"${co['used']:.2f} of ${co['cap']:.2f} for {month}", role="")
        for r in (gh_.get("costs") or {}).get("roles") or []:
            if r.get("cap") and r.get("used", 0) >= r["cap"] and heartbeat.scope(r["role"], month) not in asked:
                add("budget", f"role:{r['role']} stopped: budget spent", "", "",
                    f"${r['used']:.2f} of ${r['cap']:.2f} for {month}", role=r["role"])
        for tk in gh_.get("tickets") or []:
            if tk.get("escalated_to") == "founder":
                add("escalation", f"#{tk.get('number')} {tk.get('title', '')}", tk.get("url", ""), tk.get("updated"),
                    f"escalated to you by role:{tk.get('role') or '?'}", role=tk.get("role", ""), number=tk.get("number"))
        for tk in gh_.get("tickets") or []:
            d = when_of(tk.get("updated"))
            if tk.get("claimed") and not tk.get("blocked") and d and (now - d).total_seconds() >= stale_hours * 3600:
                hours = (now - d).total_seconds() / 3600
                stuck.append({"kind": "ticket", "number": tk.get("number"), "role": tk.get("role", ""),
                              "title": tk.get("title", ""), "url": tk.get("url", ""), "hours": round(hours)})
                add("stuck", f"#{tk.get('number')} {tk.get('title', '')}", tk.get("url", ""), tk.get("updated"),
                    f"claimed by role:{tk.get('role') or '?'}, no update for {round(hours)} hours", role=tk.get("role", ""))
        last: dict[str, dict[str, Any]] = {}
        for e in (gh_.get("costs") or {}).get("entries") or []:
            last[e.get("role", "")] = e
        for role, e in sorted(last.items()):
            if e.get("outcome") == "failed":
                stuck.append({"kind": "agent", "role": role, "title": f"role:{role}'s last run failed",
                              "url": e.get("session", ""), "at": e.get("at", "")})
                add("stuck", f"role:{role}'s last run failed", e.get("session", ""), e.get("at"),
                    f"on #{e['ticket']}" if e.get("ticket") else "", role=role)
    words = set(repo.get("approved_words") or ["Approved"])
    for d in road.get("decisions_waiting") or []:
        if d.get("status") not in words:
            add("decision", f"{d.get('id')}: {d.get('decision', '')}", "", d.get("date"),
                f"{d.get('status') or 'Open'} in {d.get('register') or 'a register'}")
    for b in road.get("blockers") or []:
        add("founder item", b.get("item", ""), "", "", f"needed by {b['needed_by']}" if b.get("needed_by") else "")
    rank = {"escalated": 0, "overdue": 1, "new": 2}
    items.sort(key=lambda x: (rank[x["level"]], NEED_ORDER.index(x["kind"]), -(x["age_days"] or 0)))
    counts = {k: sum(x["kind"] == k for x in items) for k in NEED_ORDER}
    return {"items": items, "counts": counts, "stuck": stuck, "stale_hours": stale_hours,
            "overdue": sum(x["level"] != "new" for x in items)}


def github_data(root: Path, cfg_dash: dict[str, Any], month: str, now: dt.datetime | None = None) -> dict[str, Any]:
    repo = approval.repo_name(root)
    if not repo:
        return {"ok": False, "why": "can't tell which GitHub repo this is"}
    hub = tickets.Hub(repo)
    limit = int(cfg_dash.get("activity_limit") or 200)
    try:
        logs = hub.tickets("all", tickets.LOG)
        activity = tickets.parse_log(all_comments(hub, logs[0]["number"])) if logs else []
        open_tickets = [{"number": t["number"], "title": t.get("title", ""), "url": t.get("html_url", ""),
                         "role": tickets.role_of(t), "claimed": tickets.CLAIMED in tickets.labels_of(t),
                         "blocked": tickets.BLOCKED in tickets.labels_of(t),
                         "goal": goals.objective_of(tickets.labels_of(t)),
                         "review": tickets.reviewer_of(t),
                         "escalated_to": next((lb[len(tickets.ESCALATED):] for lb in tickets.labels_of(t)
                                               if lb.startswith(tickets.ESCALATED)), ""),
                         "created": t.get("created_at", ""), "updated": t.get("updated_at", "")} for t in hub.tickets("open")]
        pulls = hub.api("pulls?state=closed&sort=updated&direction=desc&per_page=20") or []
        merged = [{"number": p["number"], "title": p.get("title", ""), "url": p.get("html_url", ""),
                   "by": (p.get("user") or {}).get("login", ""), "merged": p.get("merged_at", "")}
                  for p in pulls if p.get("merged_at")]
        first = (now or dt.datetime.now(dt.timezone.utc)).replace(day=1)
        before = (first - dt.timedelta(days=1)).strftime("%Y-%m")
        recent_runs = heartbeat.entries(heartbeat.Costs(hub, before).comments(), before)
        c = costs(hub, root, month, now)
        try:
            ctl = control.read(hub, root)
        except (subprocess.CalledProcessError, ValueError, KeyError, TypeError):
            ctl = {"all": None, "roles": {}, "url": "", "unknown": True}
        return {"ok": True, "control": ctl, "repo": repo, "activity": activity[-limit:], "tickets": open_tickets,
                "approvals": approvals(hub, root), "costs": c, "merged": merged,
                "trends": trends(recent_runs + c["entries"], activity, merged, now)}
    except (subprocess.CalledProcessError, FileNotFoundError, ValueError, KeyError, TypeError) as exc:
        return {"ok": False, "repo": repo, "why": f"GitHub unavailable or unexpected reply ({type(exc).__name__})"}


# --- the page --------------------------------------------------------------------------------------------

def embed(data: Any) -> str:
    """JSON that is safe inside a <script> element, whatever the text in it says."""
    text = json.dumps(data, ensure_ascii=False, separators=(",", ":"))
    for ch, esc in (("<", "\\u003c"), (">", "\\u003e"), ("&", "\\u0026"), (" ", "\\u2028"), (" ", "\\u2029")):
        text = text.replace(ch, esc)
    return text


def https_url(url: Any) -> str:
    """An https address safe to put in a link, or ''."""
    url = str(url or "").strip()
    return url if re.fullmatch(r"https://[^\s\"'<>]+", url) else ""


def setup(root: Path, offline: bool, now: dt.datetime) -> list[dict[str, str]]:
    """The doctor's findings for the Setup card; never stops the build."""
    try:
        return doctor.run(root, offline=offline, now=now)
    except Exception as exc:  # noqa: BLE001 - the page still builds
        return [doctor.item("doctor", "Setup check", "unknown", f"the check itself failed ({type(exc).__name__})")]


def build(root: Path, offline: bool = False, now: dt.datetime | None = None) -> dict[str, Any]:
    now = now or dt.datetime.now(dt.timezone.utc)
    cfg_dash = settings(root)
    proj = s.project(root)
    head = (s.git(root, "log", "-1", "--format=%h%n%cI") or "").split("\n")
    month = now.strftime("%Y-%m")
    data = {
        "project": {"name": proj.get("name", ""), "one_line": proj.get("one_line", ""), "repo": proj.get("repo", ""),
                    "stage": proj.get("stage")},
        "commit": head[0] if head and head[0] else "", "commit_date": head[1] if len(head) > 1 else "",
        "built": now.strftime("%Y-%m-%dT%H:%M:%SZ"), "month": month,
        "links": {"portfolio": https_url(cfg_dash.get("portfolio_url")),
                  "portfolio_name": " ".join(str(cfg_dash.get("portfolio_name") or "").split())[:80]},
        "repo": repo_data(root, cfg_dash),
        "setup": setup(root, offline, now),
        "github": {"ok": False, "why": "built offline"} if offline else github_data(root, cfg_dash, month, now),
    }
    try:
        hours = float(cfg_dash.get("stale_hours") or STALE_HOURS)
    except (TypeError, ValueError):
        hours = STALE_HOURS
    data["needs"] = needs_you(data, now, hours)
    data["money"] = money(root, data, month)
    repo_name = data["github"].get("repo") or proj.get("repo", "")
    data["rebuild_url"] = (f"https://github.com/{repo_name}/actions/workflows/dashboard.yml"
                           if re.fullmatch(r"[A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+", str(repo_name)) else "")
    return data


def money(root: Path, data: dict[str, Any], month: str) -> dict[str, Any]:
    """Runway from founder/finance.json, with AI spend from the cost log: the month-end forecast when there is one."""
    c = (data.get("github") or {}).get("costs") if (data.get("github") or {}).get("ok") else None
    ai, basis = 0.0, "unknown"
    if c:
        ai, basis = (c["forecast"], "forecast") if c.get("forecast") is not None else (c.get("total") or 0.0, "so far")
    out = finance.summary(finance.load(root), float(ai), month)
    out["ai_basis"] = basis
    return out


def page(data: dict[str, Any]) -> str:
    name = data["project"]["name"] or "Startup"
    before, _, after = s.read(PAGE).partition("__S2S_DATA__")
    return before.replace("__S2S_TITLE__", html.escape(f"{name} dashboard")) + embed(data) + after


def clip(text: Any, n: int = 300) -> str:
    text = str(text or "")
    return text if len(text) <= n else text[: n - 1] + "…"


def goal_summary(g: dict[str, Any]) -> dict[str, Any]:
    """The goal and each active objective's progress: titles and numbers, never the reasons or history."""
    objs = [o for o in g.get("objectives") or [] if o.get("status") == "active"]
    return {"goal": clip(g.get("goal"), 200),
            "objectives": [{"id": o.get("id"), "title": clip(o.get("title"), 120), "quarter": o.get("quarter", ""),
                            "progress": o.get("progress")} for o in objs][:6]}


def summary(data: dict[str, Any]) -> dict[str, Any]:
    """What a portfolio shows for this venture: counts and short lists, never the business documents."""
    repo, gh_ = data.get("repo") or {}, data.get("github") or {}
    road = repo.get("roadmap") or {}
    stages, slices = road.get("stages") or [], road.get("slices") or []
    cur = next((x for x in stages if x.get("stage") == road.get("current_stage")), {})
    building = [x for x in slices if re.search(r"progress|building", str(x.get("status")), re.I)]
    out: dict[str, Any] = {
        "schema": SUMMARY_SCHEMA, "project": data.get("project") or {}, "commit": data.get("commit", ""),
        "built": data.get("built", ""), "month": data.get("month", ""),
        "stage": {"number": road.get("current_stage"), "phase": cur.get("phase", ""), "name": cur.get("name", "")},
        "slices": {"total": len(slices), "done": sum(str(x.get("status")).lower() == "done" for x in slices),
                   "building": [clip(f"{x.get('id')}: {x.get('name')}", 120) for x in building][:3]},
        "trace": [{k: c.get(k) for k in ("level", "done", "total", "pct")} for c in (repo.get("trace") or {}).get("chain") or []],
        "blockers": [{"item": clip(b.get("item"), 200), "needed_by": b.get("needed_by", "")} for b in road.get("blockers") or []][:10],
        "decisions_waiting": [{"id": d.get("id"), "decision": clip(d.get("decision"), 200), "status": d.get("status"),
                               "date": d.get("date", "")} for d in road.get("decisions_waiting") or []][:10],
        "goals": goal_summary(repo.get("goals") or {}),
        "github": {"ok": bool(gh_.get("ok")), "why": gh_.get("why", "")},
    }
    if gh_.get("ok"):
        open_t = gh_.get("tickets") or []
        roles = (gh_.get("costs") or {}).get("roles") or []
        out["github"].update({
            "approvals_waiting": [{k: a.get(k) for k in ("number", "title", "url", "gate", "by", "created")}
                                  for a in gh_.get("approvals") or [] if a.get("open") and a.get("state") == "waiting"][:20],
            "tickets": {"open": len(open_t), "claimed": sum(bool(t.get("claimed")) for t in open_t),
                        "blocked": sum(bool(t.get("blocked")) for t in open_t)},
            "costs": {"total": (gh_.get("costs") or {}).get("total", 0),
                      "cap": round(sum(r.get("cap") or 0 for r in roles), 4),
                      "roles": [{k: r.get(k) for k in ("role", "used", "cap")} for r in roles if r.get("cap") or r.get("used")]},
            "activity": [{**{k: a.get(k) for k in ("role", "action", "ticket", "to", "at")}, "why": clip(a.get("why"))}
                         for a in (gh_.get("activity") or [])[-20:]],
            "merged": (gh_.get("merged") or [])[:5],
        })
    m = data.get("money") or {}
    if m.get("set"):
        out["money"] = {k: m.get(k) for k in ("currency", "mrr", "net_burn", "runway_months", "profitable", "as_of")}
    needs = data.get("needs") or {}
    out["needs"] = {"counts": needs.get("counts") or {}, "overdue": needs.get("overdue", 0),
                    "stuck": len(needs.get("stuck") or [])}
    return out


def cmd_build(a: argparse.Namespace) -> int:
    data = build(a.root, a.offline)
    if a.summary:
        a.summary.parent.mkdir(parents=True, exist_ok=True)
        a.summary.write_text(json.dumps(summary(data), ensure_ascii=False, indent=1), encoding="utf-8", newline="\n")
    out = (a.out or a.root / ".dashboard")
    out.mkdir(parents=True, exist_ok=True)
    (out / "index.html").write_text(page(data), encoding="utf-8", newline="\n")
    (out / "robots.txt").write_text("User-agent: *\nDisallow: /\n", encoding="utf-8", newline="\n")
    gh_ok = data["github"].get("ok")
    print(f"wrote {out / 'index.html'} at {data['commit'] or 'no commit'}; GitHub data: "
          + ("included" if gh_ok else f"missing ({data['github'].get('why')})"))
    return 0


# --- hosting: Cloudflare Pages behind Cloudflare Access, or Vercel behind Vercel Authentication ---------------------------------------------------

def http(url: str, headers: dict[str, str] | None = None) -> tuple[int, dict[str, str], str]:
    """One GET without following redirects: (status, headers, body). Raises OSError if unreachable."""
    class NoRedirect(urllib.request.HTTPRedirectHandler):
        def redirect_request(self, *args: Any, **kwargs: Any) -> None:
            return None
    req = urllib.request.Request(url, headers={"User-Agent": "solo-to-scale-dashboard", **(headers or {})})
    try:
        with urllib.request.build_opener(NoRedirect).open(req, timeout=20) as resp:
            return resp.status, dict(resp.headers), resp.read(400_000).decode("utf-8", "replace")
    except urllib.error.HTTPError as err:
        return err.code, dict(err.headers or {}), (err.read(400_000) or b"").decode("utf-8", "replace")


def covers(entry: str, host: str) -> bool:
    """Does one Access application domain entry protect the whole of `host`?"""
    entry = re.sub(r"^https?://", "", (entry or "").strip().lower())
    name, _, path = entry.partition("/")
    if path not in ("", "*"):
        return False  # protects only part of the site
    if name == host:
        return True
    return name.startswith("*.") and host.endswith(name[1:]) and host != name[2:]


def login_policy(app: dict[str, Any]) -> str:
    """'' if the app's policies require a login for specific people, else why not."""
    policies = app.get("policies")
    if not isinstance(policies, list) or not policies:
        return "has no policies"
    for p in policies:
        decision = str(p.get("decision") or "").lower()
        if decision in ("bypass", "non_identity"):
            return f"has a {decision} policy, which lets anyone in"
        if decision == "allow" and any("everyone" in (rule or {}) for rule in p.get("include") or []):
            return "allows everyone"
    if not any(str(p.get("decision") or "").lower() == "allow" for p in policies):
        return "has no allow policy"
    return ""


def access_apps(account: str, token: str) -> list[dict[str, Any]]:
    apps, page_no = [], 1
    while True:
        status, _, body = http(f"{CF_API}/accounts/{account}/access/apps?per_page=100&page={page_no}",
                               {"Authorization": f"Bearer {token}"})
        data = json.loads(body or "{}")
        if status != 200 or not data.get("success"):
            raise ValueError(f"Cloudflare API answered {status}")
        apps += data.get("result") or []
        info = data.get("result_info") or {}
        if page_no >= int(info.get("total_pages") or 1):
            return apps
        page_no += 1


def protection(apps: list[dict[str, Any]], host: str) -> str:
    """'' if a self-hosted Access app with a login policy covers host, else why not."""
    reasons = []
    for app in apps:
        entries = [app.get("domain") or "", *(app.get("self_hosted_domains") or []),
                   *((d or {}).get("uri", "") for d in app.get("destinations") or [] if (d or {}).get("type", "public") == "public")]
        if str(app.get("type") or "self_hosted") != "self_hosted" or not any(covers(e, host) for e in entries):
            continue
        why = login_policy(app)
        if not why:
            return ""
        reasons.append(f"Access app {app.get('name') or app.get('id')!r} {why}")
    return "; ".join(reasons) or "no Cloudflare Access application covers it"


def provider(cfg: dict[str, Any]) -> str:
    """'cloudflare' (the default) or 'vercel'; anything else is returned as is, and guard refuses it."""
    return str(cfg.get("provider") or "cloudflare").strip().lower()


def targets(cfg: dict[str, Any]) -> tuple[str, str]:
    host = str(cfg.get("host") or "").strip().lower()
    key = "vercel_project" if provider(cfg) == "vercel" else "cloudflare_pages_project"
    proj = str(cfg.get(key) or "").strip().lower()
    return host, proj


def project_ok(cfg: dict[str, Any]) -> bool:
    """Is the project name well formed for the provider (and the optional Vercel team)?"""
    proj = targets(cfg)[1]
    if provider(cfg) == "vercel":
        team = str(cfg.get("vercel_team") or "").strip().lower()
        return bool(VERCEL_PROJECT.match(proj)) and (not team or bool(VERCEL_TEAM.match(team)))
    return bool(PAGES_PROJECT.match(proj))


def vercel_get(path: str, cfg: dict[str, Any], token: str) -> dict[str, Any]:
    team = str(cfg.get("vercel_team") or "").strip().lower()
    scope = ("&" if "?" in path else "?") + (f"teamId={team}" if team.startswith("team_") else f"slug={team}") if team else ""
    status, _, body = http(f"{VC_API}{path}{scope}", {"Authorization": f"Bearer {token}"})
    if status != 200:
        raise ValueError(f"Vercel API answered {status}")
    data = json.loads(body or "{}")
    if not isinstance(data, dict):
        raise ValueError("Vercel API answered something unexpected")
    return data


def vercel_domains(cfg: dict[str, Any], token: str) -> list[str]:
    proj = targets(cfg)[1]
    data = vercel_get(f"/v9/projects/{proj}/domains?limit=100", cfg, token)
    return [str(d.get("name") or "").lower() for d in data.get("domains") or [] if isinstance(d, dict)]


def vercel_protection(project: dict[str, Any], domains: list[str], host: str) -> str:
    """'' if the Vercel project serves host and needs a login on every deployment, else why not."""
    if project.get("link"):
        return ("is connected to a Git repository; the dashboard needs its own Vercel project, or a deploy would "
                "replace that app")
    if host not in domains:
        return f"doesn't have {host} as a domain"
    sso = project.get("ssoProtection")
    kind = str((sso or {}).get("deploymentType") or "") if isinstance(sso, dict) else ""
    if kind != "all":
        return ("has Vercel Authentication " + (f"on '{kind}' only" if kind else "off")
                + "; it must be on 'All Deployments', or the production domain stays public")
    return ""


def cmd_guard(a: argparse.Namespace) -> int:
    return guard(settings(a.root), a.github_output)


def guard(cfg: dict[str, Any], github_output: str, file: str = "founder/dashboard.json", what: str = "dashboard",
          section: str = "The startup dashboard") -> int:
    """Shared by the dashboard and the portfolio: deploy only behind a login (Cloudflare Access or Vercel)."""
    def out(deploy: bool, project: str = "", **extra: str) -> None:
        if github_output:
            with open(github_output, "a", encoding="utf-8") as f:
                f.write(f"deploy={'yes' if deploy else 'no'}\nproject={project}\n"
                        + "".join(f"{k}={v}\n" for k, v in extra.items()))
    host, proj = targets(cfg)
    via = provider(cfg)
    if not host and not proj:
        print(f"hosting not set up ({file} has no host): built only, not deployed")
        out(False)
        return 0
    if via not in PROVIDERS:
        print(f"{file}: provider must be one of {', '.join(PROVIDERS)}, not {via!r}: not deployed")
        out(False)
        return 1
    if via == "vercel":
        return guard_vercel(cfg, out, file, what, section)
    if not HOST.match(host) or not project_ok(cfg):
        print(f"{file}: host must be a domain like pm.example.com and cloudflare_pages_project a "
              "Pages project name (lower-case letters, digits, hyphens): not deployed")
        out(False)
        return 1
    token, account = os.environ.get("CLOUDFLARE_API_TOKEN", ""), os.environ.get("CLOUDFLARE_ACCOUNT_ID", "")
    if not token or not re.fullmatch(r"[0-9a-f]{32}", account):
        print("CLOUDFLARE_API_TOKEN or CLOUDFLARE_ACCOUNT_ID isn't set as a repository secret: built only, not deployed."
              f" The founder adds them (handbook: '{section}').")
        out(False)
        return 0
    try:
        apps = access_apps(account, token)
    except (OSError, ValueError, TypeError, AttributeError) as exc:
        print(f"can't read the Cloudflare Access applications ({exc}); the token needs Access: Apps and Policies"
              " Read: not deployed")
        out(False)
        return 1
    problems = [f"{h}: {why}" for h in (host, f"{proj}.pages.dev") if (why := protection(apps, h))]
    if problems:
        print(f"not deployed: the {what} must sit behind a login.\n  " + "\n  ".join(problems)
              + "\nAdd a self-hosted Cloudflare Access application covering both, with an allow policy for your"
                " own email addresses.")
        out(False)
        return 1
    print(f"{host} and {proj}.pages.dev are behind a Cloudflare Access login: deploy")
    out(True, proj)
    return 0


def guard_vercel(cfg: dict[str, Any], out: Any, file: str, what: str, section: str) -> int:
    host, proj = targets(cfg)
    if not HOST.match(host) or not project_ok(cfg):
        print(f"{file}: host must be a domain like pm.example.com, vercel_project a Vercel project name (lower-case "
              "letters, digits, '.', '_', '-') and vercel_team empty, a team slug or a team_ id: not deployed")
        out(False)
        return 1
    token = os.environ.get("VERCEL_TOKEN", "")
    if not token:
        print(f"VERCEL_TOKEN isn't set as a repository secret: built only, not deployed. The founder adds it "
              f"(handbook: '{section}').")
        out(False)
        return 0
    try:
        project = vercel_get(f"/v9/projects/{proj}", cfg, token)
        domains = vercel_domains(cfg, token)
    except (OSError, ValueError, TypeError, AttributeError) as exc:
        print(f"can't read the Vercel project {proj!r} ({exc}); check the token's scope and vercel_team: not deployed")
        out(False)
        return 1
    why = vercel_protection(project, domains, host)
    org, pid = str(project.get("accountId") or ""), str(project.get("id") or "")
    if not why and not (VERCEL_ID.match(org) and VERCEL_ID.match(pid)):
        why = "has no readable project or account id"
    if why:
        print(f"not deployed: the {what} must sit behind a login.\n  Vercel project {proj!r} {why}."
              "\nIn the project's Settings, Deployment Protection, turn on Vercel Authentication for All Deployments.")
        out(False)
        return 1
    print(f"{host} and every deployment of the Vercel project {proj!r} need a Vercel login: deploy")
    out(True, proj, provider="vercel", vercel_org=org, vercel_project_id=pid)
    return 0


def exposed(url: str, marker: str = MARKER) -> str:
    """'' when an anonymous request doesn't get the page, 'unreachable' or 'EXPOSED' otherwise."""
    try:
        status, _, body = http(url)
    except OSError:
        return "unreachable"
    return "EXPOSED" if status == 200 and marker in body else ""


def cmd_verify(a: argparse.Namespace) -> int:
    return verify(settings(a.root))


def addresses(cfg: dict[str, Any]) -> list[str]:
    """Every address the site answers at, for the anonymous-visitor check."""
    host, proj = targets(cfg)
    if provider(cfg) != "vercel":
        return [host, f"{proj}.pages.dev"]
    names = [host, f"{proj}.vercel.app"]
    token = os.environ.get("VERCEL_TOKEN", "")
    if token:
        try:
            names += vercel_domains(cfg, token)
        except (OSError, ValueError, TypeError, AttributeError) as exc:
            print(f"can't list the Vercel project's domains ({exc}); checking {host} and {proj}.vercel.app")
    return [n for i, n in enumerate(names) if n and HOST.match(n) and n not in names[:i]]


def verify(cfg: dict[str, Any], marker: str = MARKER, what: str = "dashboard") -> int:
    host, proj = targets(cfg)
    if not HOST.match(host) or not project_ok(cfg) or provider(cfg) not in PROVIDERS:
        print("hosting not set up: nothing to verify")
        return 0
    fix = "Turn on Vercel Authentication for All Deployments" if provider(cfg) == "vercel" else "Turn on Cloudflare Access"
    bad = 0
    for url in (f"https://{name}/" for name in addresses(cfg)):
        state = exposed(url, marker)
        if state == "EXPOSED":
            bad = 1
            print(f"EXPOSED: {url} serves the {what} without a login. {fix} for it now.")
        elif state:
            print(f"{url}: unreachable (DNS or the custom domain may not be set up yet)")
        else:
            print(f"{url}: behind the login")
    return bad


def main(argv: list[str] | None = None) -> int:
    common = argparse.ArgumentParser(add_help=False)
    common.add_argument("--root", type=Path, default=s.ROOT, help=argparse.SUPPRESS)
    ap = argparse.ArgumentParser(description="The startup dashboard")
    sub = ap.add_subparsers(dest="cmd", required=True)
    b = sub.add_parser("build", parents=[common])
    b.add_argument("--out", type=Path)
    b.add_argument("--offline", action="store_true", help="skip GitHub")
    b.add_argument("--summary", type=Path, help="also write the portfolio summary here")
    sub.add_parser("guard", parents=[common]).add_argument("--github-output", default="")
    sub.add_parser("verify", parents=[common])
    a = ap.parse_args(argv)
    return {"build": cmd_build, "guard": cmd_guard, "verify": cmd_verify}[a.cmd](a)


if __name__ == "__main__":
    sys.exit(main())
